#!/usr/bin/env bash
# Q1 upgrade bundle 2: harness v2 (per-token NLL + gen-seed outputs),
# eps-SLO analysis scripts, and the GPU job queue.
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing Q1 upgrade bundle 2..."
decode "src/tokenguard/llm/thinking.py" << 'B64EOF'

B64EOF
decode "scripts/ntc_w1_thinking.py" << 'B64EOF'

B64EOF
decode "scripts/ntc_w1_stats.py" << 'B64EOF'

B64EOF
decode "scripts/ntc_w1_figures.py" << 'B64EOF'

B64EOF
decode "scripts/ntc_joint_router.py" << 'B64EOF'

B64EOF
decode "run_queue.sh" << 'B64EOF'

B64EOF
chmod +x run_queue.sh
echo ""
echo "Installed. Steps:"
echo "  # A) instant re-analysis with the eps-SLO knob:"
echo "  python scripts/ntc_w1_stats.py --probes experiments/ntc/w1_math500_Qwen3-4B.json"
echo "  python scripts/ntc_joint_router.py --small experiments/ntc/w1_math500_Qwen3-1.7B.json --large experiments/ntc/w1_math500_Qwen3-4B.json"
echo "  # B) queue ALL remaining GPU runs (9 jobs, billing-safe time limits):"
echo "  bash run_queue.sh --dry    # inspect first"
echo "  bash run_queue.sh          # submit"